\textup{\cite{LZD2012}}\label{d:lowerset}
A finite nonempty set
$\Xi\subset \mathbb{F}^2$ of distinct points is \emph{Cartesian} if and only if there exists
a lower set $\mathcal{A}\subset \mathbb{N}_0^2$ and two injective functions $\mathrm{x, y}:\mathbb{N}_0\rightarrow \mathbb{F}$ such that $\Xi$ can be written as
\begin{equation}\label{e:lowerset}
\Xi=\left\{\left(\mathrm{x}(i), \mathrm{y}(j)\right)\in \mathbb{F}^2: (i, j)\in \mathcal {A}\right\}.
\end{equation}
$\Xi$ is also called $\mathcal{A}$-\emph{Cartesian}.

\textup{\cite{Cra2004}}\label{t:lowercar}
A finite nonempty set $\Xi\subset \mathbb{F}^2$ is Cartesian if and only if
$S_x(\Xi)=S_y(\Xi)$.

\label{c:asxsy}
If a finite nonempty set $\Xi\subset \mathbb{F}^2$ is $\mathcal{A}$-Cartesian, then $\mathcal{A}=S_x(\Xi)=S_y(\Xi)$. Consequently, \eqref{e:lowerset} can be rewritten as
\begin{align}
    \Xi=&\left\{\left(\mathrm{x}(i), \mathrm{y}(j)\right)\in \mathbb{F}^2: (i, j)\in S_x(\Xi)\right\}\label{e:newlowersetx}\\
       =&\left\{\left(\mathrm{x}(i), \mathrm{y}(j)\right)\in \mathbb{F}^2: (i, j)\in S_y(\Xi)\right\}\label{e:newlowersety}.
\end{align}

\label{t:lower}
A finite nonempty set $\Xi\subset \mathbb{F}^2$ with decompositions \eqref{e:decom} is
Cartesian if and only if
\begin{equation}\label{e:pix}
    \pi_x(\Xi_0^x) \supseteq \pi_x(\Xi_1^x) \supseteq \cdots \supseteq \pi_x(\Xi_{\#\pi_y(\Xi)-1}^x)
\end{equation}
or
\begin{equation}\label{e:piy}
  \pi_y(\Xi_0^y) \supseteq \pi_y(\Xi_1^y) \supseteq \cdots \supseteq \pi_y(\Xi_{\#\pi_x(\Xi)-1}^y).
\end{equation}

\textup{\cite{Sau2004}}\label{t:Sauer}
Let $\Xi\subset \mathbb{F}^2$ be an $\mathcal{A}$-Cartesian set. Then Gr\"{o}bner \'{e}scalier $\mathcal{N}_\prec(\mathcal {I}(\Xi))$
w.r.t. any monomial order $\prec$ is identical to
\begin{equation}\label{e:lowerbas}
\mathfrak{M}_\mathcal{A}:=\{x^iy^j: (i, j)\in \mathcal {A}\}.
\end{equation}

\label{d:tower}
  Keep the notation above. A finite nonempty set $\Xi$ in $\mathbb{F}^2$ is termed $x$-\emph{tower} (resp. $y$-\emph{tower}) if $S_x(\Xi)$ is $x$-strict \textup{(}resp. $S_y(\Xi)$ is $y$-strict\textup{)} and there exist two injective functions $\mathrm{x, y}:\mathbb{N}_0\rightarrow \mathbb{F}$ as well as $\mathrm{b}_y(S_x(\Xi))+1$ \textup{(}resp. $\mathrm{b}_x(S_y(\Xi))+1$\textup{)} permutations $\sigma_0^x, \ldots, \sigma_{\mathrm{b}_y(S_x(\Xi))}^x$ \textup{(}resp. $\sigma_0^y, \ldots, \sigma_{\mathrm{b}_x(S_y(\Xi))}^y$\textup{)} of set $\{0, 1, \ldots, \mathrm{b}_x(S_x(\Xi))\}$ \textup{(}resp. $\{0, 1, \ldots, \mathrm{b}_y(S_y(\Xi))\}$\textup{)} such that $\Xi$ can be written as
\begin{align}
    \Xi :=& \{(\mathrm{x}(\sigma_j^x(i)),\mathrm{y}(j)): (i,j)\in S_x(\Xi) \}\label{e:towerx}\\
    \mbox{\textup{(}resp. }\Xi :=& \{(\mathrm{x}(i),\mathrm{y}(\sigma_j^y(j))): (i,j)\in S_y(\Xi) \}\textup{)}\label{e:towery}.
\end{align}

\label{t:towerc}
A finite nonempty set $\Xi\subset \mathbb{F}^2$ with decompositions \eqref{e:decom} is
$x$-tower \textup{(}resp. $y$-tower\textup{)} if and only if $S_x(\Xi)$ is $x$-strict \textup{(}resp. $S_y(\Xi)$ is $y$-strict\textup{)} and
\begin{align*}
    \pi_x(\Xi_0^x) &\supsetneq \pi_x(\Xi_j^x),\quad j=1,2,\ldots, \#\pi_y(\Xi)-1\\
    (\mbox{resp. } \pi_y(\Xi_0^y) &\supsetneq \pi_y(\Xi_i^y),\quad i=1,2,\ldots, \#\pi_x(\Xi)-1).
\end{align*}
